const pages = $input.all().map(item => item.json || {});
const webhookBody = $('Zen_New_Comment_Webhook').first().json?.body || {};
const detail = webhookBody.detail && typeof webhookBody.detail === 'object'
  ? webhookBody.detail
  : {};
const eventComment = webhookBody.event?.comment && typeof webhookBody.event.comment === 'object'
  ? webhookBody.event.comment
  : {};

if (!pages.length) {
  throw new Error('Get_ECS_Case_Comment returned no pages');
}

const comments = pages.flatMap(page =>
  Array.isArray(page.comments) ? page.comments : []
);
const users = pages.flatMap(page =>
  Array.isArray(page.users) ? page.users : []
);
if (!comments.length) {
  throw new Error('Zendesk comments response is empty');
}

const firstCount = pages[0]?.count;
const expectedCount =
  firstCount === null || firstCount === undefined || firstCount === ''
    ? null
    : Number(firstCount);
const lastPage = pages[pages.length - 1];
if (
  lastPage.next_page != null ||
  (expectedCount !== null && Number.isFinite(expectedCount) && comments.length !== expectedCount)
) {
  throw new Error(
    'Zendesk comment snapshot is incomplete: expected=' + expectedCount + ', received=' + comments.length
  );
}

const ticketId = String(detail.id || '').trim();
const eventCommentId = String(eventComment.id || '').trim();
if (!/^\d+$/.test(ticketId)) {
  throw new Error('Zendesk ticket id is missing or not numeric');
}
if (!/^\d+$/.test(eventCommentId)) {
  throw new Error('Zendesk webhook comment id is missing or not numeric');
}
if (!comments.some(comment => String(comment.id) === eventCommentId)) {
  throw new Error('Webhook comment ' + eventCommentId + ' is not present in the Zendesk snapshot');
}

const userById = new Map(
  users
    .filter(user => user && user.id !== null && user.id !== undefined)
    .map(user => [String(user.id), user])
);

function staffFlag(value) {
  if (!value || typeof value !== 'object') {
    return null;
  }
  if (typeof value.is_staff === 'boolean') return value.is_staff;
  if (typeof value.is_agent === 'boolean') return value.is_agent;
  const role = String(value.role || '').trim().toLowerCase();
  if (['agent', 'admin', 'staff', 'support'].includes(role)) return true;
  if (['end-user', 'end_user', 'customer', 'requester', 'user'].includes(role)) return false;
  return null;
}

const commentsPayload = comments.map(comment => {
  const commentId = String(comment.id);
  const commentAuthorId =
    comment.author_id === null || comment.author_id === undefined
      ? null
      : String(comment.author_id);
  const currentAuthor = commentId === eventCommentId ? eventComment.author || {} : {};
  const user = commentAuthorId ? userById.get(commentAuthorId) : null;
  const userIsAgent = staffFlag(user);
  const webhookIsAgent = commentId === eventCommentId ? staffFlag(currentAuthor) : null;
  if (userIsAgent !== null && webhookIsAgent !== null && userIsAgent !== webhookIsAgent) {
    throw new Error('Author identity conflict for comment ' + commentId);
  }
  const isAgent = userIsAgent !== null ? userIsAgent : webhookIsAgent;
  return {
    id: commentId,
    public: typeof comment.public === 'boolean' ? comment.public : comment.is_public === true,
    author: {
      id: commentAuthorId,
      name: user?.name || comment.author_name || currentAuthor.name || null,
      role: isAgent === true ? 'agent' : isAgent === false ? 'end-user' : 'unknown',
      is_agent: isAgent,
    },
    body: String(comment.body ?? comment.plain_body ?? ''),
    via_channel: comment.via?.channel ?? null,
    created_at: comment.created_at,
    attachments: (Array.isArray(comment.attachments) ? comment.attachments : []).map(a => ({ attachment_id: String(a.id), file_name: String(a.file_name || ''), content_type: String(a.content_type || 'application/octet-stream'), size_bytes: Number(a.size || 0), inline: a.inline === true, source_comment_id: commentId })),
  };
});

const sourceUpdatedAt = String(
  detail.updated_at || webhookBody.time || eventComment.created_at || commentsPayload.at(-1)?.created_at || ''
).trim();
if (!sourceUpdatedAt) {
  throw new Error('source_updated_at is missing');
}

const status = String(detail.status || 'open').trim().toLowerCase();
if (!['new', 'open', 'pending', 'hold', 'solved', 'closed'].includes(status)) {
  throw new Error('Zendesk ticket status is invalid: ' + status);
}

const requester = detail.requester && typeof detail.requester === 'object'
  ? detail.requester
  : webhookBody.requester && typeof webhookBody.requester === 'object'
    ? webhookBody.requester
    : {};
const organization = detail.organization && typeof detail.organization === 'object'
  ? detail.organization
  : null;

return [{
  json: {
    schema_version: 'automation-intake-v1',
    event_id: 'zendesk:ticket:' + ticketId + ':comment:' + eventCommentId,
    event_type: 'comment.created',
    occurred_at: sourceUpdatedAt,
    ticket: {
      id: ticketId,
      status,
      subject: String(detail.subject || ''),
      description: String(detail.description || ''),
      requester: {
        id: requester.id == null ? (detail.requester_id == null ? null : String(detail.requester_id)) : String(requester.id),
        name: requester.name == null ? null : String(requester.name),
        email: requester.email == null ? null : String(requester.email),
        role: requester.role == null ? 'end-user' : String(requester.role),
        is_agent: typeof requester.is_agent === 'boolean' ? requester.is_agent : false,
      },
      organization: organization
        ? {
            id: organization.id == null ? null : String(organization.id),
            name: organization.name == null ? null : String(organization.name),
            email: organization.email == null ? null : String(organization.email),
            role: organization.role == null ? null : String(organization.role),
            is_agent: typeof organization.is_agent === 'boolean' ? organization.is_agent : null,
          }
        : null,
      tags: Array.isArray(detail.tags) ? detail.tags.map(tag => String(tag)) : [],
      custom_fields: detail.custom_fields && typeof detail.custom_fields === 'object'
        ? detail.custom_fields
        : {},
      updated_at: detail.updated_at || null,
    },
    comment_snapshot: {
      source_updated_at: sourceUpdatedAt,
      snapshot_complete: true,
      trigger_comment_id: eventCommentId,
      comments: commentsPayload,
    },
  },
}];
